(window.webpackJsonp=window.webpackJsonp||[]).push([[1,41,42,43,44,45,46,47],{314:function(e,t,o){var map={"./airforce-hr.md":336,"./heals-health-application.md":337,"./ny-cake-academy-website.md":338,"./paylocity.md":339,"./token-strategy.md":340,"./workflow-builder.md":341,"./zenith-design-system.md":342};function n(e){var t=l(e);return o(t)}function l(e){if(!o.o(map,e)){var t=new Error("Cannot find module '"+e+"'");throw t.code="MODULE_NOT_FOUND",t}return map[e]}n.keys=function(){return Object.keys(map)},n.resolve=l,e.exports=n,n.id=314},336:function(e,t){e.exports={attributes:{title:"Air Force HR Platform",type:"portfolio",category:"ui-ux-design",client:"BAM",position:"UX Manager & Platform Strategist",role:"Lead Designer, Strategist, and Design System Architect",tools:"Adobe XD & OutSystems",image:"/projects/my-vector/thumbnail.png",tags:"ux design",url:"/projects/my-vector/case-study.pdf",link:"/projects/my-vector/case-study.pdf",linkText:"View Case Study",linkTitle:" ",dateStart:"June 2021",dateEnd:"November 2022",featuredImage:"/projects/my-vector/featured-image.png",description:"Functioned as UX Manager and Platform Strategist for an enterprise platform. Developed design thinking toolkit and championed the movement of design as part of development teams. Built out design operation processes, such as file management, onboarding, and interviewing. Was responsible for building out Information Architecture and Project Road Map for the Design System.",cModules:{moduleOne:{item:"pdf",header:"Platform Strategy",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/my-vector/case-study.pdf",style:""}}},html:""}},337:function(e,t){e.exports={attributes:{title:"HEALS Health Application",type:"portfolio",client:"RPI-IBM HEALS PROGRAM",category:"ui-ux-design",display:"featured",media:"Design Thinking | Design Research | UI/UX Design | Front-End Dev.",dateStart:"August 2020",dateEnd:"May 2021",position:"Design Research Assistant",role:"UI/UX Designer & Front-end Developer",tools:"Adobe XD & Nuxt.JS",link:"/projects/heals/case-study.pdf",linkText:"View Case Study",linkTitle:"Project Overview",description:"Worked to develop a health application prototype with a team of researchers. Application designed for user testing and proof of concWept. Developed and executed design research methodology to aid in UI/UX design development.",image:"/projects/heals/thumbnail.png",tags:"ux design",featuredImage:"/projects/heals/featured-image.png",cModules:{moduleOne:{item:"text",header:"Design Goal",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 backdrop-secondary",style:"padding: 40px 56px; border-radius: 16px;",inner:{itemOne:{style:"font-size: 1.2rem;",class:"padding-bottom-base padding-top-base",text:"Individuals with diabetes are given guidelines to follow to help live a healthier lifestyle; however, those guidelines are often difficult to understand and are not accompanied by information regarding how to better adhere to them."},itemTwo:{style:"font-size: 1.2rem; color: var(--color-primary); font-weight: 500",class:"padding-bottom-base",text:"How do we help individuals with diabetes to lead a healthier lifestyle?"},itemThree:{style:"font-size: 1.4rem; color: var(--color-primary-60); font-weight: 700;",class:"padding-bottom-base",text:"Assumptions"},itemFour:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"Individuals with diabetes are not adhering to the necessary health guidelines"},itemFive:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"Part of the reason why people do not follow the guidelines is because they do not know how"},itemSix:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"Presently, if an individual with diabetes wants to receive custom guidance on how to better adhere to the necessary guidelines, they need to go to a nutritionist or an expert."},itemSeven:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"People do not go to nutritionists because of the high cost."},itemEight:{style:"font-size: 1.15rem;",class:"padding-bottom-small",text:"If people had custom guidance, they would follow it"}}},moduleTwo:{item:"text",header:"User Research",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"",inner:{itemOne:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"Prior to me joining the project, there was an initial proof of concept application built that was used for user testing."},itemTwo:{style:"font-size: 1.3rem; color: var(--color-primary); font-weight: 700",class:"padding-bottom-small",text:"Users felt..."},itemThree:{style:"font-size: 1.15rem;",class:"padding-bottom-small",text:"The design felt outdated."},itemFour:{style:"font-size: 1.15rem;",class:"padding-bottom-small",text:"It didn’t feel like a mobile app."},itemFive:{style:"font-size: 1.15rem;",class:"padding-bottom-small",text:"It wasn’t clear what the point of the application was."},itemSix:{style:"font-size: 1.15rem;",class:"padding-bottom-small",text:"It was difficult to navigate through the platform"},itemSeven:{style:"font-size: 1.2rem; font-weight: 600; color: var(--color-secondary-tints-80);",class:"padding-top-base",text:"The majority of user’s reported that they saw value in the technology but would not use it."}}},moduleThree:{item:"text",header:"Assessment: What it Does Well",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"",inner:{itemOne:{style:"font-size: 1.15rem; padding-top: 8px;",class:"padding-bottom-base",text:"Central navigation that is easy to access."},itemTwo:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"Once in the different areas of the application, there is a lot of great information available for the user."},itemThree:{style:"font-size: 1.15rem;",text:"The sitemap is simple but breaks up the information into clear areas that make sense for the end-user."}}},moduleFour:{item:"text",header:"Assessment: Room for Improvement",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"",inner:{itemOne:{style:"font-size: 1.15rem; padding-top: 8px;",class:"padding-bottom-base",text:"The application has no clear ‘homepage’ or landing page. To get information, the user must click into the different spaces."},itemTwo:{style:"font-size: 1.15rem",class:"padding-bottom-base",text:"The chat feature is only accessible through the main menu."},itemThree:{style:"font-size: 1.15rem",class:"padding-bottom-base",text:"While the designated spaces are well-organized, there is no easy way to jump between them."},itemFour:{style:"font-size: 1.15rem",text:"The information provided is detailed, but it lacks a clear hierarchy."}}},moduleFive:{item:"text",header:"Design Considerations",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"border-bottom: solid var(--color-primary);",inner:{itemOne:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"How to differentiate the personalized content from the scripted/standard information?"},itemTwo:{style:"font-size: 1.3rem; font-weight: 600;",class:"padding-bottom-base padding-top-small",text:"UI/UX Should"},itemThree:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"Communicate Authority, Inform, Build/Alter Behavior(s), Empower, Promote a Healthier Lifestyle, Encourage"},itemFour:{style:"font-size: 1.3rem; font-weight: 600;",class:"padding-bottom-base padding-top-small",text:"Solution Requirements"},itemFive:{style:"font-size: 1.15rem;",class:"padding-bottom-small padding-top-small",text:"Should differentiate the personalized content from the rest."},itemSix:{style:"font-size: 1.15rem;",class:"padding-bottom-small padding-top-small",text:"Not all personalized content should be considered equal—we want to highlight where the ‘why’ is provided."},itemSeven:{style:"font-size: 1.15rem;",class:"padding-bottom-small padding-top-small",text:"When the why is being provided, it should be clear what it is about."},itemEight:{style:"font-size: 1.15rem;",class:"padding-bottom-small padding-top-small",text:"The end solution should be accessible."},itemNine:{style:"font-size: 1.15rem;",class:"padding-bottom-small padding-top-small",text:"Feedback should be positive and negative—when seeking to alter behaviors, it is just as important to tell people what they are doing that is correct."}}},moduleEight:{item:"text",header:"Research Methods",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"border-bottom: solid var(--color-primary);",inner:{itemOne:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"Other research methods done, but not showcased here in this case study"},itemTwo:{style:"font-size: 1.15rem; font-weight: 600",class:"",text:"Competitive analysis of similar software"},itemThree:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"Looked specifically at AI software and behavior-altering/habit-building software."},itemFour:{style:"font-size: 1.15rem; font-weight: 600",class:"",text:"Visual research and frequency mapping for color palette"},itemFive:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"Curated a series of images related to the platform's key initiative and used them to construct a color palette based on the results from a frequency analysis."},itemSix:{style:"font-size: 1.15rem; font-weight: 600",class:"",text:"Informal discussions with nutritionists"},itemSeven:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"We conducted several informal interviews with a nutritionist to get their insight into how to make the application as useful to people with diabetes as possible. "}}},moduleSix:{item:"image",header:"Personalized Health Knowledge Graph",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/heals/knowledge-graph.svg",style:""},moduleSeven:{item:"image",header:"Information Diagram",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/heals/information-diagram.svg",style:""},moduleNine:{item:"image",header:null,class:"col-xs-12 col-sm-12 col-md-5 col-lg-5",image:"/projects/heals/heals-mockup.png",style:""},moduleTen:{item:"text",header:"Solution",class:"col-xs-12 col-sm-12 col-md-7 col-lg-7",style:"border-bottom: solid var(--color-primary);",inner:{itemOne:{style:"font-size: 1.15rem;",class:"padding-bottom-base padding-top-small",text:"A health application that provides personalized advice for individuals with diabetes. The application should provide a detailed analysis of the individual’s behaviors and use that knowledge to make suggestions about their diet. The application should be able to be fully integrated with a food logger system, and it should provide recommendations in the form of written advice or recipes."},itemTwo:{style:"font-size: 1.15rem; color: var(--color-primary);",class:"padding-bottom-base",text:"Personalized information and advice will be provided to the individual by an AI Health Advisor. This information should be seen as most important and given the greatest weight within the end design. The application will contain advice at varying levels of personalization. For example, a user will be shown the guidelines that are most relevant to them; however, those guidelines come from a pre-defined list. The personal experience comes through in the ‘why.’ The novelty of the application is the ability to provide the individual with the ‘why.’"}}},moduleEleven:{item:"button",header:"XD Prototype Embed",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:null,inner:{contents:{src:"https://xd.adobe.com/view/c310aa74-64ad-4b84-ac1c-cb387f0b0fd4-9643/",text:"View in New Tab"}}},moduleTwelve:{item:"iframe",header:null,class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 phoneHolder",inner:{src:"https://xd.adobe.com/embed/c310aa74-64ad-4b84-ac1c-cb387f0b0fd4-9643/"}}}},html:""}},338:function(e,t){e.exports={attributes:{title:"NY Cake Academy Website",type:"portfolio",client:"A series of mockups from the NY Cake Academy site.",category:"ui-ux-design",media:"Graphic Design | Illustration | Digital Design | Marketing | Content Management",dateStart:"Summer 2018",dateEnd:"Winter 2020",link:"https://www.figma.com/proto/7yXQR1cqCPXJ66FfDLKNvL/NY-Cake-Academy?page-id=0%3A1&node-id=54%3A7749&viewport=6265%2C2087%2C0.48&scaling=scale-down&starting-point-node-id=54%3A7749",linkText:"View Prototype",linkTitle:"Prototype",position:"Digital Designer",description:"The work displayed below is a recreation of the website I developed while working for NY Cake. The original website was built using Wordpress, but it is no longer being used. The recreation is fairly close to the original, but does contain some enhancements.",role:"Brand Manager, Designer, and Developer",tools:"Figma, Divi Builder, & Wordpress",image:"/projects/academy-website/thumbnail.png",tags:"Graphic Design, Illustration, Digital Design, Marketing, Content Management",featuredImage:"/projects/academy-website/featured-image.png",cModules:{moduleEight:{item:"text",header:"Project Brief",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-right: auto; ",inner:{itemOne:{style:"font-size: 1.0rem;",class:"padding-bottom-base",text:"NY Cake is a cake decorating company located in NYC. The company consists of several different sub-sections, but this website is specifically dealing with the Academy. NY Cake Academy is a premier cake decorating and baking school located in NYC. The website is the companies sole POS for classes. The system was intended to manage class stock and descriptions, allow instructors to easily get their class numbers and attendance sheets, and make suggestions to students based on their previous enrollments to help build retention."}}},moduleOne:{item:"iframe",header:"Components",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://www.figma.com/embed?embed_host=share&url=https%3A%2F%2Fwww.figma.com%2Ffile%2F7yXQR1cqCPXJ66FfDLKNvL%2FNY-Cake-Academy%3Fnode-id%3D54%253A9452%26t%3DOqRHw6642EavSXiQ-1"}},moduleTwo:{item:"iframe",header:"Patterns",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://www.figma.com/embed?embed_host=share&url=https%3A%2F%2Fwww.figma.com%2Ffile%2F7yXQR1cqCPXJ66FfDLKNvL%2FNY-Cake-Academy%3Fnode-id%3D54%253A9574%26t%3DbJOMW20lQlesLD6J-1"}},moduleThree:{item:"iframe",header:"Widgets",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://www.figma.com/embed?embed_host=share&url=https%3A%2F%2Fwww.figma.com%2Ffile%2F7yXQR1cqCPXJ66FfDLKNvL%2FNY-Cake-Academy%3Fnode-id%3D54%253A10304%26t%3DbJOMW20lQlesLD6J-1"}},moduleFour:{item:"iframe",header:"Website Mockup",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://www.figma.com/embed?embed_host=share&url=https%3A%2F%2Fwww.figma.com%2Fproto%2F7yXQR1cqCPXJ66FfDLKNvL%2FNY-Cake-Academy%3Fpage-id%3D0%253A1%26node-id%3D54%253A7749%26viewport%3D6265%252C2087%252C0.48%26scaling%3Dscale-down%26starting-point-node-id%3D54%253A7749"}}}},html:""}},339:function(e,t){e.exports={attributes:{title:"Paylocity's design system",subtext:"overhauled with teamwork.",type:"portfolio",client:"Paylocity",category:"ui-ux-design",media:"UI/UX Design | Design System | UX Management",display:"featured",dateStart:"April 2024",dateEnd:"November 2024",position:"Staff Product Designer",role:"Design System Lead & Architect",tools:"Figma",link:null,linkText:"Design Brief",linkTitle:"Project Planning",description:"Paylocity had an existing design system called Citrus. However, a new product language emerged, called Citrus 7. The Citrus design team (Javier, Brian, Ross, and myself) were tasked with building a new design system to support it. I helped define the best practices for creating components, established the token architecture, built component tooling, organized the system, and facilitated design-engineer collaboration.",image:"/projects/paylocity/thumbnail.png",tags:"design system",featuredImage:"/projects/paylocity/paylocity-overview.png",cModules:{moduleTwo:{item:"image",header:"Design token improvements",subheader:"to improve the way we work.",description:"I led the token architecture with support from Javier Jacome, a senior product designer on the project. The previous token architecture lacked component-level tokens, which was crucial in implementing the new product language. This new architecture aligns with industry standards and helped enable seemless switching between themes. Additionally, we based our token naming and structure on W3C guidance.",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",blockclass:"background-secondary padding-xxxl border-radius-md",imgstyle:"max-width: 960px; justify-self: center",image:"/projects/paylocity/new-architecture.webp"},moduleThree:{item:"image",header:"Proof of concept",subheader:"with our engineering partners.",description:"Since our design token architecture was improved, we were able to design with our previous product language (Citrus 6) in conjunction with Citrus 7. We utilized variables and modes to view changes in Figma. This acted as a proof of concept for our engineering team to implement on the coded components.",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",blockclass:"background-secondary padding-xxxl border-radius-md",imgstyle:"max-width: 960px; justify-self: center",image:"/projects/paylocity/poc.png"},moduleFour:{item:"image",header:"Building atomically",subheader:"through team collaboration.",description:"All designers on the Citrus team contributed. Together we collaborated to construct components in Figma that balanced the needs of aligning with code and having the best practices in Figma. We held an atomic design approach for building components. By doing this, designers could solve and design for user context more efficiently.",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",blockclass:"background-secondary padding-xxxl border-radius-md",imgstyle:"max-width: 960px; justify-self: center",image:"/projects/paylocity/atomic.webp"},moduleFive:{item:"image",header:"Handing off design",subheader:"with good documentation.",description:"As components were designed, I set the team up with handoff documents that went into detail about a component. In this handoff, we would detail interactions, components needed, props, notes, etc. This document acted as the main anchor point between our engineers, designers, QA, and product.",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",blockclass:"background-secondary padding-xxxl border-radius-md",imgstyle:"max-width: 960px; justify-self: center",image:"/projects/paylocity/handoff.webp"}}},html:""}},340:function(e,t){e.exports={attributes:{title:"Design System Token Strategy",type:"portfolio",category:"ui-ux-design",client:"Paylocity",display:"featured",position:"Staff Designer",role:"Lead Designer & Design System Architect",tools:"Figma",image:"/projects/citrus-design-system/thumbnail.png",tags:"design system",url:"https://www.figma.com/proto/aImBvKBHCpKkCDgGFq1OeJ/Citrus-Tokens?page-id=0%3A1&type=design&node-id=21-2099&viewport=7343%2C1529%2C0.42&t=MUT4XmmYyAa1JpAo-1&scaling=scale-down&mode=design",link:"https://www.figma.com/proto/aImBvKBHCpKkCDgGFq1OeJ/Citrus-Tokens?page-id=0%3A1&type=design&node-id=21-2099&viewport=7343%2C1529%2C0.42&t=MUT4XmmYyAa1JpAo-1&scaling=scale-down&mode=design",linkText:"View Presentation",dateStart:"March 2023",dateEnd:"August 2023",media:"UI/UX Design | Design System | UX Management",featuredImage:"/projects/citrus-design-system/featured-image.png",cModules:{moduleOne:{item:"text",header:"Objective",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 backdrop-secondary",style:"padding: 40px 56px; border-radius: 16px;",inner:{itemOne:{style:"font-size: 1.4rem; color: var(--color-primary-60); font-weight: 700;",class:"padding-bottom-base padding-top-base",text:"create a robust token framework that enables the following:"},itemTwo:{style:"font-size: 1.15rem; color: var(--color-primary); font-weight: 400",class:"padding-bottom-base",text:"citron styling as a form of design system adoption"},itemThree:{style:"font-size: 1.15rem; color: var(--color-primary); font-weight: 400",class:"padding-bottom-base",text:"efficient updates and product evolution"},itemFour:{style:"font-size: 1.15rem; color: var(--color-primary); font-weight: 400",class:"padding-bottom-base",text:"consistent styling throughout the system"},itemFive:{style:"font-size: 1.15rem; color: var(--color-primary); font-weight: 400",class:"padding-bottom-base",text:"** bonus ** dark mode theming"}}},moduleTwo:{item:"text",header:"Key Terms",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"",inner:{itemOne:{style:"font-size: 1.1rem;",class:"padding-bottom-base padding-top-base",text:"tokens: an explicit value that can be used within a programming language. Within design systems, they are used to standardize values for different design properties"},itemTwo:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"figma variables: equatable to tokens for development; they are identifiers used to standardize styling across a system"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"figma styles: equatable to class and ID styling for development; they are a series of style properties that can easily be applied to an element"},itemFour:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"alias: a token or Figma variable whose value is another token or variable"},itemFive:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"mode: a feature in Figma that allows you to ‘theme’ areas of the platform; a common example of this is ‘light’ and ‘dark’ modes"}}},moduleThree:{item:"text",header:"Assessment of System ",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-bottom: 8px;"},moduleFour:{item:"image",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/design-system-audit.png",style:"margin-top: 0px;"},moduleFive:{item:"text",header:" ",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemOne:{style:"font-size: 1.1rem; padding-top: 8px; font-weight:700;",class:"",text:"naming conventions"},itemTwo:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"color tokens refer to specific color names rather than semantic use cases"},itemThree:{style:"font-size: 1.1rem; padding-top: 8px; font-weight:700;",class:"",text:"architecture"},itemFour:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"token architecture is flat, which does not allow for cascading updates and brand evolution"},itemFive:{style:"font-size: 1.1rem; padding-top: 8px; font-weight:700;",class:"",text:"usage guidance"},itemSix:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"token names lack clear use case and individual styles do not have descriptions to help designers understand when/where/how/why a specific style should be used resulting in inconsistent treatments for things like interactive states within the platform and component library "}}},moduleSix:{item:"text",header:"Considerations for Rearchitecting the System",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 ",style:"margin-bottom: 8px;"},moduleSeven:{item:"text",header:" ",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemZero:{style:"font-size: 2.0rem; font-weight:700;",class:"",text:"#1"},itemOne:{style:"font-size: 1.2rem; font-weight:700;",class:"",text:"consideration:"},itemTwo:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"mitigating the impact on paylocity customer"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"how do we build a robust token system and begin to apply it to components incrementally without disrupting the end-user experience "},itemFour:{style:"font-size: 1.2rem; font-weight:700;",class:"",text:"strategic solution:"},itemFive:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"subtle changes"},itemSix:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"while building out the system there will need to be changes made to the colors, type sizing, and other design parameters; these changes should be subtle and unnoticeable to the untrained eye"},itemSeven:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"any drastic changes to the system should be assessed to determine if the risk out-weighs the reward"},itemEight:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"while updating colors and other values within the system, test screens should be used to verify the applicability of new values and subtlety of changes"}}},moduleEight:{item:"text",header:" ",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6x",style:"margin-top: 0px;",inner:{itemZero:{style:"font-size: 2.0rem; font-weight:700;",class:"",text:"#2"},itemOne:{style:"font-size: 1.2rem; font-weight:700;",class:"",text:"consideration:"},itemTwo:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"change management"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"how do we mitigate risk and help designers and developers to adopt this new way of working"},itemFour:{style:"font-size: 1.2rem; font-weight:700;",class:"",text:"strategic solution:"},itemFive:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"communication"},itemSix:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"prior to asking teams to adopt the new tooling, time should be spent to educate teams on what the new system is, how it works, when they will be expected to adopt it, and—most importantly—why the changes are being made"},itemSeven:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"removing barriers"},itemEight:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"an education strategy should be constructed to help teach designers and developers how to use the new tooling and what its benefits are"},itemNine:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"beta testing should be done with a small group of designers who have opted in to using the new tools to help gather feedback, so that we can improve upon the system prior to releasing it"}}},moduleNine:{item:"image",header:"Token Path Throughout System",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/citrus-design-system/token-path-filled.png",style:""},moduleTen:{item:"image",header:"Foundational Theme Tokens",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/foundations.png",style:""},moduleEleven:{item:"image",header:"Token Naming Conventions",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/token-naming.png",style:""},moduleTwelve:{item:"text",header:"Design System Designers Building in Figma",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-bottom: 8px;"},moduleThirteen:{item:"image",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/modes.png",style:""},moduleFourteen:{item:"image",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/modes-ex.png",style:""},moduleFifteen:{item:"image",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",image:"/projects/citrus-design-system/building-ex.png",style:""},moduleSeventeen:{item:"text",header:"All Designers Building in Figma",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-bottom: 0;",inner:{itemOne:{style:"font-size: 1.1rem;",class:"padding-top-base padding-bottom-base",text:"Designers consuming the design system have two options for applying citron tokens to their designs. This is similar to how, in development, a design system’s styling can be applied using css variables or using classes that are intended to define a single property. This helps to overcome Figma's limitation of not being able to see variable descriptions when referencing them."}}},moduleEighteen:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-top: 0px; margin-bottom: 0;",inner:{itemZero:{style:"font-size: 1.4rem; font-weight:700;",class:"",text:"Option #1: Theme Tokens"},itemOne:{style:"font-size: 1.1rem;",class:"",text:"design tokens built using figma’s new variable feature"}}},moduleNineteen:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemTwo:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"",text:"Features"},itemThree:{style:"font-size: 1.1rem; font-weight:500;",class:"padding-top-base",text:"scoped properties"},itemFour:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"clearly defining what a color or numerical value can be used to define helps to minimize misuse"},itemFive:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"aliases"},itemSix:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"variables can equal other variables, which allows for cascading value changes within the system"},itemSeven:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"modes"},itemEight:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"allows for easily switching context of components when building out components, minimizing duplicate efforts"},itemNine:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"padding/spacing"},itemTen:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"using variables to define border radii, padding, and spacing helps to ensure consistency throughout platform design"}}},moduleTwenty:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemTwo:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"",text:"Limitations / Features Not Yet Available"},itemThree:{style:"font-size: 1.1rem; font-weight:500;",class:"padding-top-base",text:"token descriptions"},itemFour:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"while you can add descriptions to tokens, those tokens are not visible outside of the Figma collection that you define them in"}}},moduleTwentyone:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-top: 0px; margin-bottom: 0;",inner:{itemZero:{style:"font-size: 1.4rem; font-weight:700;",class:"",text:"Option #2: Theme Styles"},itemOne:{style:"font-size: 1.1rem;",class:"",text:"reusable styles, for colors styles equal color variables"}}},moduleTwentytwo:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemTwo:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"",text:"Features"},itemThree:{style:"font-size: 1.1rem; font-weight:500;",class:"padding-top-base",text:"style descriptions"},itemFour:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"having descriptions containing the intended use case for a style property available for designers when referencing a color can help minimize misuse and confusion"},itemFive:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"text styles"},itemSix:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"reusable text styles helps to ensure consistent type treatment within the product, improves designer efficiency during the prototype building process, and enables systemwide style updates"},itemSeven:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"mixed colors"},itemEight:{style:"font-size: 1.1rem",class:"padding-bottom-base",text:"creating color styles that equal multiple hex values or variables allows designers to easily apply modern interaction styling techniques to their applications and ensures consistent treatment of interaction states"}}},moduleTwentythree:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top: 0px;",inner:{itemTwo:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"",text:"Limitations / Features Not Yet Available"},itemThree:{style:"font-size: 1.1rem; font-weight:500;",class:"padding-top-base",text:"alias"},itemFour:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"styles can be made from tokens (variables), but they cannot be made from other styles"}}},moduleTwentyfour:{item:"text",header:"Current Engineer Implementation",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"margin-bottom: 0;"},moduleTwentyfive:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top:0; ",inner:{itemOne:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"padding-bottom-base",text:"Overview"},itemTwo:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"front-end style strategy: built using CSS-in-JS"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"global classes can be created, but only as a last resort"},itemFour:{style:"font-size: 1.1rem;",class:"",text:"Current system architecture requires the tokens to be flattened and consumed as a JSON file, as a result, we are unable to easily apply modern design system conventions within our system."}}},moduleTwentysix:{item:"text",header:"",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"margin-top:0;",inner:{itemOne:{style:"font-size: 1.2rem; font-weight:700; border-bottom: 2px solid; padding-bottom: 8px;",class:"padding-bottom-base",text:"Current Pain Points"},itemTwo:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"barrier for entry/learning curve"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"a way to enable teams to easily consume styles within the system is by using ‘groups’ or classes that redefine what a token equals based off of some class or state"},itemFour:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"need to build empathy"},itemFive:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"lack of knowledge from people on the citrus team regarding the work processes for developers and designers using tokens"},itemSix:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"need to consider user experience"},itemSeven:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"design system tooling is a user experience and should use UX processes for building out intuitive tooling"},itemEight:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"need to validate assumptions"},itemNine:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"process decisions are being made based on assumptions because of a lack of bandwidth to test for validation"},itemTen:{style:"font-size: 1.1rem; font-weight: 500;",class:"",text:"cumbersome update process"},itemEleven:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"process for getting tokens updated and delivered to the customer is overly cumbersome"}}},moduleTwentyseven:{item:"image",header:"Team Work Processes: Updating Tokens",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/citrus-design-system/update.png",style:"margin-top: 0px;"},moduleTwentyeight:{item:"text",header:"Modern Token Conventions",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"",inner:{itemOne:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"grouped tokens"},itemTwo:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"a way to enable teams to easily consume styles within the system is by using ‘groups’ or classes that redefine what a token equals based off of some class or state"},itemThree:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"dynamic redefinition"},itemFour:{style:"font-size: 1.1rem;",class:"",text:"this allows you to redefine what a value equals based off of some situational context; this could include interactions, brand theming, states, media queries, etc."},itemFive:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"easy refresh"},itemSix:{style:"font-size: 1.1rem;",class:"",text:"modern design systems typically have a way to easily refresh references to different tokens within our team"},itemSeven:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"aliases"},itemEight:{style:"font-size: 1.1rem;",class:"",text:"aliases are used in enterprise design systems to allow for styling to be cascaded throughout the system and can help to enable ease of updates as the product evolves"},itemNine:{style:"font-size: 1.1rem; font-weight:500;",class:"",text:"classes"},itemTen:{style:"font-size: 1.1rem;",class:"",text:"classes are typically used to communicate all of the style properties for an element. This is beneficial when sharing design attributes for things like type elements"}}},moduleTwentynine:{item:"image",header:"**Revised** Team Work Processes: Updating Tokens",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/citrus-design-system/ideal-update.png",style:"margin-top: 0px;"}}},html:""}},341:function(e,t){e.exports={attributes:{title:"Workflow Builder",type:"portfolio",client:"HR Workflow Builder",category:"ui-ux-design",display:"featured",media:"Design Thinking | UI/UX Design",dateStart:"August 2021",dateEnd:"November 2022",position:"UX Manager & Platform Strategist",role:"Contributor and Strategist",tools:"Adobe XD & Outsystems",link:"/projects/workflow-builder/case-study.pdf",linkText:"View Case Study",linkTitle:"Project Overview",description:"Worked to develop a workflow builder for the US Air Force to use within their HR application, MyVector. The builder was designed to allow for admins to come into the platform and create custom work processes. The initial use case was for the Air Force’s application process.",image:"/projects/workflow-builder/thumbnail.png",tags:"ux design",featuredImage:"/projects/workflow-builder/featured-image.png",cModules:{moduleOne:{item:"text",header:"Design Problem",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 backdrop-secondary",style:"padding: 40px 56px; border-radius: 16px;",inner:{itemOne:{style:"font-size: 1.2rem;",class:"padding-bottom-base padding-top-base",text:"Presently, every time a new application process or form needs to be added to the MyVector platform, it requires assistance from developers at BAM Technologies. This leads to inefficiencies for the Air Force and BAM Technologies employees. In addition, within the MyVector platform there are similar functionalities being built out that relate to one another, such as building out questionnaires and forms, but there is no central location for admins to access this information."},itemTwo:{style:"font-size: 1.2rem; color: var(--color-primary); font-weight: 500",class:"padding-bottom-base",text:"How do we help empower administrative users to be able to create the tools and resources that they need without requiring external intervention?"},itemThree:{style:"font-size: 1.4rem; color: var(--color-primary-60); font-weight: 700;",class:"padding-bottom-base",text:"Assumptions"},itemFour:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"Administrative users want to be able to create their own processes"},itemFive:{style:"font-size: 1.15rem;",class:"padding-bottom-base",text:"There is enough overlap in these processes that we can create a generic structure for administrative users to use to create their custom workflows."}}},moduleTwo:{item:"text",header:"Solution",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"",inner:{itemOne:{style:"font-size: 1.2rem; font-weight: 700;",class:"padding-bottom-base padding-top-base",text:"A series of ‘builders’ that allow administrative users to create their own content for their processes."},itemTwo:{style:"font-size: 1.1rem; color: var(--color-primary); font-weight: 700",class:"",text:"Form Builder"},itemThree:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"A custom form builder that allows users to create their own intake forms or questionnaires."},itemFour:{style:"font-size: 1.1rem; color: var(--color-primary); font-weight: 700",class:"",text:"Workflow Builder"},itemFive:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"A custom flow builder that allows users to create their own workflow processes based off of some triggering action."},itemSix:{style:"font-size: 1.1rem; color: var(--color-primary); font-weight: 700",class:"",text:"Email Builder"},itemSeven:{style:"font-size: 1.1rem;",class:"padding-bottom-base",text:"A custom email builder to create emails that can be used in automatic communication systems."},itemEight:{style:"font-size: 1.2rem; font-weight: 700;",class:"padding-bottom-base padding-top-base",text:"The goal of the software is to empower administrative users to create their own custom content and processes."}}},moduleThree:{item:"text",header:"Initial Implementation",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",style:"",inner:{itemTwo:{style:"font-size: 1.1rem;",class:"padding-bottom-base padding-top-base",text:"For the initial implementation we will be focusing on the application process and building out the data services for the additional builders. In this implementation all of the additional builders will exist as 'widgets' within the workflow builder process."}}},moduleFour:{item:"text",header:"Users",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"",inner:{itemOne:{style:"font-size: 1.15rem; padding-top: 8px;",class:"padding-bottom-small",text:"Coordination Groups"},itemTwo:{style:"font-size: 1.15rem",class:"padding-bottom-small",text:"Workflow Admins"},itemThree:{style:"font-size: 1.15rem",class:"padding-bottom-small",text:"Airman"},itemFour:{style:"font-size: 1.15rem",class:"padding-bottom-small",text:"Spaceman"},itemFive:{style:"font-size: 1.15rem",class:"",text:"IT Admin"}}},moduleFive:{item:"text",header:"Initiatives",class:"col-xs-12 col-sm-12 col-md-6 col-lg-6",style:"",inner:{itemOne:{style:"font-size: 1.15rem; padding-top: 8px;",class:"padding-bottom-small",text:"Managing workflow"},itemTwo:{style:"font-size: 1.15rem",class:"padding-bottom-small",text:"Applying for a ________"},itemThree:{style:"font-size: 1.15rem",class:"padding-bottom-small",text:"Coordinating workflows"},itemFour:{style:"font-size: 1.15rem",class:"",text:"Managing applications"}}},moduleSix:{item:"image",header:"Process Flow",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/process-flow.svg",style:""},moduleSeven:{item:"image",header:"Workflow Builder: Full View",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/featured-image.png",style:""},moduleEight:{item:"image",header:"Adding Single Participants",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/add-single.png",style:""},moduleNine:{item:"image",header:"Adding Groups of Participants",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/add-group.png",style:""},moduleTen:{item:"image",header:"Editing Recipient Order",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/editing-order.png",style:""},moduleEleven:{item:"image",header:"Configuration",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/configuration.png",style:""},moduleTwelve:{item:"image",header:"Communication Configuration",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/comm-config.png",style:""},moduleThirteen:{item:"image",header:"Reminder Configuration",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12",image:"/projects/workflow-builder/reminder-config.png",style:""}}},html:""}},342:function(e,t){e.exports={attributes:{title:"Zenith Design System",type:"portfolio",client:"Undisclosed",category:"ui-ux-design",media:"UI/UX Design | Design System | UX Management",display:"featured",dateStart:"June 2021",dateEnd:"November 2022",position:"UX Manager & Platform Strategist",role:"Project Lead & Design System Architect",tools:"XD & Outsystems",link:"https://lucid.app/documents/view/b6fb047f-72b2-4068-b73e-3d3a4de55eee",linkText:"View Style Guide IA",linkTitle:"Information Architecture",description:"A fully themeable design system that was initially created for an enterprise platform. Went on to be expanded upon so that it could be used by any project that the company took on.",image:"/projects/zenith-design-system/thumbnail.png",tags:"design system",featuredImage:null,cModules:{moduleOne:{item:"text",header:"Design Goal",class:"col-xs-12 col-sm-12 col-md-5 col-lg-4",style:"margin-right: auto; ",inner:{itemOne:{style:"font-size: 1.0rem;",class:"padding-bottom-base",text:"Development teams are tasked with creating intuitive user experiences consistent across the platform. Presently, there is a lack of consistency between created mockups and executed designs, as well as a lack of continuity throughout the platform."},itemTwo:{style:"font-size: 1.0rem; color: var(--color-primary); font-weight: 700",class:"padding-bottom-base",text:"How can we empower teams to meet platform standards better and deliver the best UX possible?"},itemThree:{style:"font-size: 1.1rem; color: var(--color-primary-60); font-weight: 600;",class:"padding-bottom-base",text:"Assumptions"},itemFour:{style:"",class:"padding-bottom-base",text:"The reason for the lack of consistency is that there is no onboarding or training process for individuals coming in. In addition, there is no central location where best practices are documented and shared."},itemFive:{style:"",class:"padding-bottom-base",text:"If teams were to have the information and guidance needed, we would see an increase in consistency across the platform."},itemSix:{style:"",class:"padding-bottom-base",text:"The reason why repeat functionality exists within the platform is that teams were unaware that the tools they needed already existed."}}},moduleTwo:{item:"text",header:"Problem Statements",class:"col-xs-12 col-sm-12 col-md-5 col-lg-4",style:"margin-left: auto; ",inner:{itemOne:{style:"font-size: 1.0rem; font-weight: 700;",class:"padding-bottom-base",text:"Throughout the company, there are the following:"},itemFour:{style:"",class:"padding-bottom-base",text:"a lack of design resources available for individual project teams"},itemFive:{style:"",class:"padding-bottom-base",text:"repeat functionality and UI Elements being built"},itemSix:{style:"",class:"padding-bottom-base",text:"a lack of resources to resolve problems previously solved by others"},itemSeven:{style:"",class:"padding-bottom-base",text:"a lack of clearly defined standards and best practices"},itemEight:{style:"font-size: 1.0rem; font-weight: 700;",class:"padding-bottom-base",text:"Within the platform, there are the following:"},itemNine:{style:"",class:"padding-bottom-base",text:"a lack of time and resources devoted to maintaining and implementing a design system (both in design and development)"},itemTen:{style:"",class:"padding-bottom-base",text:"a lack of knowledge on how to use the design system"},itemEleven:{style:"",class:"padding-bottom-base",text:"a lack of clearly defined best practices for UI design and front-end implementation"}}},moduleThree:{item:"iframe",header:"CSS Library",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/06e34704-1115-4e52-87ce-a07ca469fcbf-53b0/"}},moduleFour:{item:"iframe",header:"CORE UI Library",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/b9de13fc-a457-4d4c-a3df-1381dbf97e85-ec8d"}},moduleFive:{item:"iframe",header:"Layout UI",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/3f0da562-e63d-4c72-957e-6ac01bc5a0cc-6a5e/"}},moduleSix:{item:"iframe",header:"Information UI",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/dc42502e-b75c-45b2-9a11-32f29634f325-8911/"}},moduleSeven:{item:"iframe",header:"Theme Patterns",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/548b91ad-95f9-4ee2-9dae-bf6256e1fec7-01d8/"}},moduleEight:{item:"iframe",header:"Icon Library",class:"col-xs-12 col-sm-12 col-md-12 col-lg-12 design-system",inner:{src:"https://xd.adobe.com/embed/6a32a1f2-fb6d-421b-b8e8-8527a50a665c-3f61/"}}}},html:""}}}]);